package com.agacostays.payroll.service.impl; import com.agacostays.payroll.dto.response.AttendanceSummaryResponse;import com.agacostays.payroll.entity.SalaryStructure;import com.agacostays.payroll.service.PayrollCalculationService;import org.springframework.stereotype.Service;import java.math.*;@Service public class PayrollCalculationServiceImpl implements PayrollCalculationService{public Result calculate(SalaryStructure s,AttendanceSummaryResponse a,int wd){BigDecimal gross=s.getMonthlyGrossSalary();int abs=a==null||a.absentDays()==null?0:a.absentDays();int half=a==null||a.halfDays()==null?0:a.halfDays();BigDecimal daily=gross.divide(BigDecimal.valueOf(Math.max(wd,1)),2,RoundingMode.HALF_UP);BigDecimal ded=daily.multiply(BigDecimal.valueOf(abs)).add(daily.multiply(BigDecimal.valueOf(half)).multiply(new BigDecimal("0.5")));BigDecimal net=gross.subtract(ded).subtract(s.getDeductions()).max(BigDecimal.ZERO);return new Result(s.getBasicSalary(),s.getHra(),s.getAllowances(),BigDecimal.ZERO,gross.setScale(2,RoundingMode.HALF_UP),ded.setScale(2,RoundingMode.HALF_UP),s.getDeductions(),net.setScale(2,RoundingMode.HALF_UP));}}